<?php $this->layout('layouts/studio'); ?>
<section class="studio-page-head"><div><p class="studio-eyebrow">Conteúdo</p><h1 class="studio-page-title"><?= $page ? 'Editar página' : 'Nova página' ?></h1><p class="studio-page-description">Configure o conteúdo e a publicação desta página.</p></div><a class="studio-btn" href="<?= url('/studio/pages') ?>">Voltar</a></section>
<section class="studio-panel"><form class="studio-form" action="<?= url('/studio/page' . ($page ? '/' . $page->id : '')) ?>" method="post" enctype="multipart/form-data"><?= csrf_input() ?><input type="hidden" name="action" value="<?= $page ? 'update' : 'create' ?>"><div class="studio-form-grid"><div><label class="studio-field studio-label">Título *<input class="studio-input" name="title" value="<?= htmlspecialchars($page->title ?? '') ?>" required></label><label class="studio-field studio-label">Endereço amigável<input class="studio-input" name="uri" value="<?= htmlspecialchars($page->uri ?? '') ?>" placeholder="exemplo-de-pagina"></label><label class="studio-field studio-label">Conteúdo *<div class="studio-organic-editor"><textarea class="mce" data-organic-editor data-editor-height="540" id="page-content" name="content" rows="20" required><?= $page->content ?? '' ?></textarea></div></label><button class="studio-btn" type="button" data-media-picker data-media-editor="page-content"><ion-icon name="image-outline"></ion-icon>Inserir imagem da biblioteca</button></div><aside><input type="hidden" id="page-library-cover" name="library_cover"><label class="studio-field studio-label">Capa<input class="studio-input" type="file" name="cover" accept="image/*"></label><button class="studio-btn studio-media-pick" type="button" data-media-picker data-media-target="#page-library-cover" data-media-preview=".page-cover-preview"><ion-icon name="images-outline"></ion-icon>Escolher da biblioteca</button><img class="studio-preview page-cover-preview <?= empty($page->cover)?'is-empty':'' ?>" src="<?= !empty($page->cover)?image($page->cover,600):'' ?>" alt="Capa atual"><label class="studio-field studio-label">Status<select class="studio-select" name="status"><option value="draft" <?= ($page->status ?? '') === 'draft' ? 'selected' : '' ?>>Rascunho</option><option value="post" <?= ($page->status ?? '') === 'post' ? 'selected' : '' ?>>Publicada</option><option value="trash" <?= ($page->status ?? '') === 'trash' ? 'selected' : '' ?>>Lixeira</option></select></label><label class="studio-field studio-label">Publicação<input class="studio-input" type="datetime-local" name="post_at" value="<?= date('Y-m-d\TH:i', strtotime($page->post_at ?? 'now')) ?>"></label><button class="studio-btn primary">Salvar página</button><?php if ($page): ?><button class="studio-btn danger" name="action" value="delete" data-confirm-submit="Excluir esta página?">Excluir página</button><input type="hidden" name="page_id" value="<?= $page->id ?>"><?php endif; ?></aside></div></form></section>
